insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-kapusta-kiszona', 'de', 'Kapusta kiszona', 'kapusta-kiszona', 'Selbst gemachtes Sauerkraut entsteht durch reine Milchsäuregärung von fein gehobeltem Weißkohl mit 2 Prozent Salz, roh und beschwert, als Vorratsgrundlage für Bigos statt als warme, bereits fertig geschmorte Beilage.', '[{"text":"Weißkohl vierteln, Strunk entfernen, sehr fein hobeln. Mit 40 g unjodiertem Salz, das entspricht 2 Prozent bei 2 kg Kohl, in einer großen Schüssel fest kneten, bis reichlich eigener Saft austritt, das dauert etwa 8 bis 12 Minuten.","tip":"Das hier ist roher Rohferment und keine fertige warme Beilage wie [Kapusta zasmażana](/de/rezepte/kapusta-zasmażana), mehr zur Technik erklärt der [Kiszenie-Guide](/de/blog/kiszenie-guide)."},{"text":"Fest in einen sauberen Steintopf oder ein großes Glas stampfen, Schicht für Schicht, bis der eigene Saft alles bedeckt. Optional etwas Kümmel dazugeben und mit einem Gewicht beschweren, zum Beispiel einem kleinen Teller mit einem gefüllten Wasserglas darauf, damit 1 bis 2 cm Lake über dem Kraut stehen.","tip":"Reicht der eigene Saft nicht aus, 200 ml Wasser mit 4 g Salz aufkochen lassen und nachgießen, niemals ungesalzenes Wasser nachfüllen, geeignete Gläser stellt die [Kaufberatung für Fermentiergläser](/de/blog/fermentier-glaeser-kaufberatung) vor."},{"text":"Bei 18 bis 22 Grad 7 bis 14 Tage gären lassen, täglich das Gewicht prüfen und aufsteigenden Schaum abschöpfen. Zeigt sich farbiger Schimmel, muss die ganze Charge weg. Danach in saubere Gläser füllen und kühl lagern.","tip":"Frisch fertig gekist ist das Kraut die Grundlage für [Bigos](/de/rezepte/bigos) und für [Kapuśniak](/de/rezepte/kapusniak), unjodiertes Salz für die nächste Charge gibt es günstig im [Polenladen](/de/blog/polenladen-einkaufen)."},{"text":"Gekühlt reift das Kraut weiter und wird milder und runder im Geschmack. Vor der Verwendung kosten, ist es zu scharf, kurz kalt abspülen, aber nicht auswaschen, sonst verliert es zu viel von seiner Säure und den nützlichen Milchsäurebakterien.","tip":"Als Nachbar im Vorratsregal passen gut die [Ogórki kiszone](/de/rezepte/ogorki-kiszone), beide entstehen durch dieselbe Milchsäuregärung ohne einen Tropfen Essig."}]'::jsonb, 'Kapusta kiszona, fein geschnittenes, roh vergorenes Weißkraut, die Basis für Bigos und Kapuśniak. Kapusta kiszona verdankt ihren festen Platz in der polnischen Küche vor allem dem Bigos, dessen Name aus dem Lateinischen für zwei Geschmäcker kommen soll, gemeint sind frischer und saurer Kohl im selben Topf. Im 17. und 18. Jahrhundert war Bigos noch ein Gericht aus gehacktem Fleisch mit Zitrone, Limette oder Weinessig, erst im 18. Jahrhundert ersetzte man die teuren sauren Zutaten zunehmend durch die deutlich günstigere kiszona Kapusta, eine Anpassung, die sich im 19. Jahrhundert endgültig durchsetzte. Traditionell wurde der geschnittene Kohl in Holzfässern mit Salz eingestampft, oft buchstäblich mit den Füßen, wie es Władysław Reymont in seinem Roman Chłopi eindrücklich beschreibt, ärmere Haushalte kisten sogar lose Blätter und Strunkreste, wenn ganze Köpfe knapp waren, weil auf den Wintervorrat niemand verzichten wollte. Die Fermentation verläuft in zwei Phasen, eine stürmische Anfangsphase von 2 bis 3 Tagen mit sichtbarer Blasenbildung und Schaum, danach die ruhigere eigentliche Milchsäuregärung bis etwa zum 10. bis 16. Tag. Bis heute zählt Polen zu den größten Sauerkrautproduzenten Europas, mit einem Pro-Kopf-Verbrauch von rund 3 kg im Jahr, und die Region um Charsznica in Kleinpolen ist für ihre Qualität so bekannt, dass dort jährlich ein eigenes Kohlfest mit gewähltem Kohlkönig gefeiert wird. Dieselbe Milchsäuregärung ohne Essig verbindet Kapusta kiszona mit den [Ogórki kiszone](/de/rezepte/ogorki-kiszone) und dem [Czosnek kiszony](/de/rezepte/czosnek-kiszony).

## Einkaufen und kochen

Kaufe festen, möglichst spät im Jahr geernteten Weißkohl, er hat mehr Zucker für die Milchsäurebakterien und wird knackiger als früher Sommerkohl. Dazu nur unjodiertes Salz, optional Kümmel für mehr Aroma, beides gibt es günstig im [Polenladen](/de/blog/polenladen-einkaufen). Für größere Mengen lohnt sich ein Steintopf oder ein großes Fermentierglas, eine Übersicht bietet die [Kaufberatung für Fermentiergläser](/de/blog/fermentier-glaeser-kaufberatung).

Zwei Prozent Salz sind bei Kapusta kiszona bewusst niedriger angesetzt als bei Gurken, weil Kohl beim Kneten viel eigenen Saft freisetzt, der die Salzkonzentration in der Lake zusätzlich verdünnt. Entscheidend ist kräftiges Kneten, bis wirklich reichlich Saft austritt, denn nur unter Flüssigkeit läuft die Gärung sauerstofffrei und ohne Fäulnis ab. Die stürmische Anfangsphase mit Schaum und Bläschen in den ersten Tagen ist normal und muss nur regelmäßig abgeschöpft werden, farbiger Schimmel dagegen bedeutet immer, dass die betroffene Charge entsorgt werden muss. Nach etwa 7 bis 14 Tagen bei 18 bis 22 Grad ist die Hauptgärung abgeschlossen, im Kühlschrank reift das Kraut danach nur noch langsam nach und wird milder.

In Deutschland lohnt sich eine größere Charge, sobald im Herbst fester Weißkohl günstig zu haben ist, denn fertig gegoren hält sich das Kraut im Kühlschrank monatelang und wird zur Wintervorratsbasis für Bigos. Kinder dürfen beim Hobeln und Schichten helfen, das feste Einstampfen und das tägliche Prüfen bleibt bei den Erwachsenen. Guten Kümmel und unjodiertes Salz gibt es im [Polenladen](/de/blog/polenladen-einkaufen).

## Am Tisch

Serviere frisch gegorene Kapusta kiszona als Basis für [Bigos](/de/rezepte/bigos) oder für [Kapuśniak](/de/rezepte/kapusniak), auch als Füllung für Pierogi funktioniert sie gut. Im Vorratsregal steht sie sinnvoll neben den [Ogórki kiszone](/de/rezepte/ogorki-kiszone).

Zu wenig Kneten lässt zu wenig Saft austreten, dann bleibt der Kohl an der Luft und verdirbt statt zu gären. Ungesalzenes Wasser zum Auffüllen verdünnt die schützende Salzkonzentration und öffnet Fäulnisbakterien Tür und Tor. Farbigen Schimmel zu übersehen statt die ganze Charge zu entsorgen ist riskant. Und wer Kapusta kiszona mit der bereits geschmorten [Kapusta zasmażana](/de/rezepte/kapusta-zasmażana) verwechselt, erwartet die falsche Konsistenz und den falschen Geschmack.

Mit Kümmel wird das Kraut würziger, mit etwas Karotte in den Schichten leicht süßer, eine ältere Landvariante kiste sogar nur lose Blätter und Strunkreste, wenn ganze Köpfe knapp waren. Wer die geschmorte, warme Beilage sucht, findet sie bei [Kapusta zasmażana](/de/rezepte/kapusta-zasmażana), der nächste Nachbar im Regal bleiben die [Ogórki kiszone](/de/rezepte/ogorki-kiszone).', 'Kapusta kiszona Rezept | Sauerkraut selbst machen | Alemniam', 'Kapusta kiszona mit 2 % Salz. Bilingual, roher Milchsäureferment, keine zasmażana, Grundlage für Bigos.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-kapusta-kiszona', 'pl', 'Kapusta kiszona', 'kapusta-kiszona', 'Domowa kapusta kiszona powstaje dzięki czystej fermentacji mlekowej z drobno szatkowanej kapusty, 2 procent soli i solidnego obciążenia, jako baza na zapas do bigosu, a nie jako gotowy ciepły dodatek prosto z patelni.', '[{"text":"Kapustę pokrój, usuń głąb, szatkuj bardzo drobno. Z 40 g soli niejodowanej, czyli 2 procent na 2 kg kapusty, ugniataj ją mocno 8 do 12 minut, aż puści dużo własnego soku.","tip":"To surowy kis, a nie gotowa ciepła [kapusta zasmażana](/pl/rezepte/kapusta-zasmażana), więcej o technice pisze [poradnik o kiszeniu](/pl/blog/kiszenie-w-domu)."},{"text":"Ubijaj kapustę warstwami w czystym naczyniu, aż własny sok całkowicie ją przykryje. Opcjonalnie dodaj kminek i obciąż całość, na przykład talerzykiem ze słoikiem wody na wierzchu, tak żeby 1 do 2 cm zalewy stało nad kapustą.","tip":"Gdy soku jest za mało, dolej zagotowane 200 ml wody z 4 g soli, nigdy samej niesolonej wody, a dobre słoiki opisuje [poradnik o słoikach do kiszenia](/pl/blog/sloiki-do-kiszenia)."},{"text":"Kiś 7 do 14 dni w temperaturze 18 do 22 stopni, codziennie sprawdzaj ciężarek i zbieraj pianę z powierzchni. Kolorowa pleśń oznacza, że trzeba wyrzucić całą partię. Potem przełóż do czystych słoików i wstaw do lodówki.","tip":"Świeżo ukiszona kapusta to baza na [bigos](/pl/rezepte/bigos) i na [kapuśniak](/pl/rezepte/kapusniak), sól niejodowaną na kolejną partię tanio kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy)."},{"text":"W lodówce kapusta dalej łagodnieje i robi się bardziej okrągła w smaku. Przed użyciem zawsze skosztuj, a jeśli jest za ostra, krótko przepłucz ją zimną wodą, ale nie wypłukuj, bo straci zbyt dużo kwasu i pożytecznych bakterii.","tip":"Sąsiadem w spiżarni dobrze bywają [ogórki kiszone](/pl/rezepte/ogorki-kiszone), obie powstają dzięki tej samej fermentacji mlekowej bez kropli octu."}]'::jsonb, 'Kapusta kiszona, drobno szatkowana, surowo ukiszona kapusta, baza pod bigos i kapuśniak. Kapusta kiszona zawdzięcza swoje stałe miejsce w polskiej kuchni przede wszystkim bigosowi, którego nazwa ma pochodzić z łaciny i oznaczać podwójny smak, czyli świeżą i kwaśną kapustę w jednym garnku. W XVII i XVIII wieku bigos był jeszcze potrawą z siekanego mięsa z cytryną, limonką albo octem winnym, dopiero w XVIII wieku te drogie kwaśne dodatki zaczęto zastępować znacznie tańszą kiszoną kapustą, a w XIX wieku ta zamiana utrwaliła się na dobre. Tradycyjnie posiekaną kapustę ubijano z solą w drewnianych beczkach, często dosłownie bosymi stopami, co barwnie opisał Władysław Reymont w Chłopach, a najbiedniejsi kisili nawet luźne liście i odcięte kawałki głąbów, byle tylko mieć zapas na zimę. Fermentacja przebiega w dwóch etapach, najpierw burzliwa faza początkowa trwająca 2 do 3 dni z wyraźnym pienieniem i wydzielaniem gazu, potem spokojniejsza właściwa fermentacja mlekowa trwająca do 10 lub 16 dnia. Polska do dziś jest jednym z największych producentów kiszonej kapusty w Europie, ze spożyciem rzędu 3 kg na osobę rocznie, a region Charsznicy w Małopolsce słynie z jej jakości na tyle, że co roku odbywa się tam własne święto kapusty z wyborem króla i królowej. Ta sama fermentacja mlekowa bez octu łączy kapustę kiszoną z [ogórkami kiszonymi](/pl/rezepte/ogorki-kiszone) i [czosnkiem kiszonym](/pl/rezepte/czosnek-kiszony).

## Zakupy i gotowanie

Kup twardą, najlepiej późno zebraną kapustę białą, ma więcej cukru dla bakterii kwasu mlekowego i zostaje bardziej chrupiąca niż wczesna kapusta letnia. Do tego tylko sól niejodowana, opcjonalnie kminek dla aromatu, oba składniki tanio kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Przy większych ilościach przyda się kamionkowy garnek albo duży słój do fermentacji, przegląd sprzętu opisuje [poradnik o słoikach do kiszenia](/pl/blog/sloiki-do-kiszenia).

Dwa procent soli w kapuście kiszonej to celowo mniej niż przy ogórkach, bo kapusta podczas ugniatania oddaje mnóstwo własnego soku, który dodatkowo rozcieńcza stężenie soli w zalewie. Kluczowe jest mocne ugniatanie, aż naprawdę popłynie sok, bo tylko pod płynem fermentacja przebiega bez dostępu tlenu i bez ryzyka zgnilizny. Burzliwa faza początkowa z pianą i bąbelkami w pierwszych dniach jest normalna i wystarczy ją regularnie zbierać, natomiast kolorowa pleśń zawsze oznacza, że dana partia nadaje się do wyrzucenia. Po około 7 do 14 dniach w 18 do 22 stopniach główna fermentacja się kończy, a w lodówce kapusta jeszcze powoli dojrzewa i łagodnieje.

W Niemczech warto ukisić większą partię, gdy jesienią tania jest twarda kapusta biała, bo gotowa trzyma się w lodówce miesiącami i staje się zimową bazą na bigos. Dzieci mogą pomagać przy szatkowaniu i układaniu warstw, mocne ugniatanie i codzienne sprawdzanie zostaje przy dorosłych. Dobry kminek i sól niejodowaną znajdziesz w [sklepie polskim](/pl/blog/sklep-polski-zakupy).

## Przy stole

Podawaj świeżo ukiszoną kapustę jako bazę do [bigosu](/pl/rezepte/bigos) albo do [kapuśniaku](/pl/rezepte/kapusniak), dobrze sprawdza się też jako nadzienie do pierogów. W spiżarni sensownie stoi obok [ogórków kiszonych](/pl/rezepte/ogorki-kiszone).

Zbyt słabe ugniatanie sprawia, że wypływa za mało soku, wtedy kapusta zostaje na powietrzu i psuje się zamiast fermentować. Dolewanie niesolonej wody rozcieńcza ochronne stężenie soli i otwiera drogę bakteriom gnilnym. Przeoczenie kolorowej pleśni zamiast wyrzucenia całej partii jest ryzykowne. A kto myli kapustę kiszoną z już duszoną [kapustą zasmażaną](/pl/rezepte/kapusta-zasmażana), oczekuje złej konsystencji i złego smaku.

Z kminkiem kapusta robi się bardziej wyrazista, z odrobiną marchewki między warstwami lekko słodsza, starsza wiejska wersja kisiła nawet same luźne liście i odcięte głąby, gdy całych główek brakowało. Kto szuka duszonej, ciepłej wersji, znajdzie ją w [kapuście zasmażanej](/pl/rezepte/kapusta-zasmażana), a najbliższym sąsiadem w spiżarni zostają [ogórki kiszone](/pl/rezepte/ogorki-kiszone).', 'Kapusta kiszona przepis | Domowy kis | Alemniam', 'Kapusta kiszona, 2 procent soli. Dwujęzycznie, surowy kis, nie zasmażana, baza do bigosu.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
